      "٣. باشتقاق الطرفين بالنسبة للزمن $t$:",
      "$$2x \\frac{dx}{dt} + 2y \\frac{dy}{dt} = 0 \\implies \\frac{dy}{dt} = -\\frac{x}{y}\\frac{dx}{dt}$$",
      "٤. بالتعويض:",
      "$$\\frac{dy}{dt} = -\\frac{6}{8}(4) = -3\\text{ م/ث}$$",
